"""Phase 2 UI/operations slice: execution lifecycle, mid-run cancellation and reconnect over the worker protocol.

This module adds NO authority. Core (the frozen server turn record and the client's execution journal) still owns
intent, approval, the ticket and the settlement; the supervisor ledger still owns admission, attempts, containment and
reconciliation. What is added, worker-side (trusted client code, never the UI):

  * `execution_proposal`: the exact proposal a UI approval is bound to (client, session, turn, kind/provider/model,
    capability, argument digest, approval digest). `execution_begin` must echo BOTH the approval digest the server
    issued and this proposal digest; a change of any authority-relevant field (another provider or model, other
    arguments, another turn) yields another digest, so the earlier approval cannot start it.
  * `ExecutionController.begin`: the approved turn is dispatched in a worker thread so the single-threaded frame
    loop keeps answering `execution_status` / `execution_cancel` / `execution_list` while the harness runs. Exactly
    one execution per client at a time (the harness pool is one slot); every other turn command is refused with
    `EXECUTION_IN_PROGRESS` meanwhile.
  * `ExecutionController.cancel`: before the approval is posted the turn is DENIED instead (nothing ever runs);
    after that and before dispatch the bridge refuses the task (`NOT_STARTED:CANCELLED`); while an attempt runs the
    executor is killed through its job object (`SupervisorBridge.cancel` -> `Supervisor.request_cancel`) and the
    outcome is `uncertain` (a kill after dispatch is never a clean close); after a terminal state the request is
    refused (`EXECUTION_TERMINAL`).
  * `ExecutionRegister`: one durable JSON record per execution under `<client_root>/control/supervisor/executions/`
    (worker-owned; the UI holds only ids). `execution_status` always re-reads the record AND the live ledger,
    journal and server turn state, so a reconnecting UI sees what URI knows, never what the UI remembered. A worker
    restart marks every non-terminal record `uncertain` (`WORKER_RESTARTED`) after the frozen journal recovery and
    the bridge's authority revocation have run; nothing is ever re-launched from a record.

Lifecycle: queued -> approving -> starting -> running -> {completed | failed | cancelled | uncertain | quota_paused}.
`completed` is set only from the server's `SETTLED_VERIFIED` (ledger COMPLETE + verified receipt); every unmapped
settlement or exception after dispatch is `uncertain`, never success.
"""
from __future__ import annotations

import re
import sqlite3
import threading
import time
import uuid
from pathlib import Path

from uri_core.client_contracts import digest
from uri_core.client_runtime.execution_journal import ExecutionJournal
from uri_core.client_runtime.turn_runner import NOT_STARTED, TurnError
from uri_core.core.runtime_identity import atomic_json

SCHEMA = "uri.phase2ops.execution.v1"
ACTIVE_STATES = ("queued", "approving", "starting", "running")
TERMINAL_STATES = ("completed", "failed", "cancelled", "uncertain", "quota_paused")
AUTHORITY_FIELDS = ("client_id", "session_id", "turn_id", "kind", "provider", "model", "capability_id",
                    "argument_digest", "approval_digest")
_ID = re.compile(r"^[0-9a-f]{32}$")
_LIST_LIMIT = 50


def execution_proposal(client_id, session_id, turn_id, reasoning, approval_request, qualification=None) -> dict:
    """The proposal a UI approval is bound to. `proposal_digest` covers exactly AUTHORITY_FIELDS; the remaining keys
    are display material taken verbatim from the server's approval request (bound through `argument_digest`)."""
    reasoning = reasoning if isinstance(reasoning, dict) else {}
    request = approval_request if isinstance(approval_request, dict) else {}
    arguments = request.get("arguments") if isinstance(request.get("arguments"), dict) else {}
    inputs = arguments.get("inputs") if isinstance(arguments.get("inputs"), dict) else {}
    core = {"client_id": client_id, "session_id": session_id, "turn_id": turn_id, "kind": reasoning.get("kind"),
            "provider": reasoning.get("provider"), "model": reasoning.get("model"),
            "capability_id": request.get("capability_id"), "argument_digest": request.get("argument_digest"),
            "approval_digest": request.get("approval_digest")}
    return {**core, "proposal_digest": digest(core), "effect": request.get("effect"), "reversible": request.get("reversible"),
            "action": arguments.get("action"), "arguments": arguments, "instruction": inputs.get("instruction"),
            "expected_file": inputs.get("expected_file"), "qualification": qualification}


def _now():
    return time.time()


def _ro(path):
    con = sqlite3.connect(f"file:{Path(path).resolve().as_posix()}?mode=ro", uri=True, timeout=2)
    con.row_factory = sqlite3.Row
    return con


def ledger_view(ledger_path, task_id):
    """Read-only view of the supervisor ledger for one task: the authoritative execution facts, never cached."""
    if not task_id or not Path(ledger_path).is_file():
        return None
    try:
        con = _ro(ledger_path)
    except sqlite3.Error as exc:
        return {"error": "LEDGER_UNREADABLE:" + type(exc).__name__}
    try:
        task = con.execute("SELECT state, reason_code, request_json FROM task WHERE task_id=?", (task_id,)).fetchone()
        if task is None:
            return {"task_id": task_id, "task": None}
        try:   # the bridge's own request row: which turn/selection/approval this task was submitted for
            import json
            req = json.loads(task["request_json"] or "{}")
            if not isinstance(req, dict):
                raise TypeError("request_json is not an object")
            request = {k: req.get(k) for k in ("turn_id", "operation_id", "session_id", "capability_id", "provider", "model",
                                               "approval_digest", "argument_digest", "expected_file", "execution_id")}
        except (ValueError, TypeError):
            request = {"error": "REQUEST_UNREADABLE"}
        attempts = [dict(r) for r in con.execute(
            "SELECT attempt_id, status, pid, pid_create_time, end_reason, exit_code, spawned_at_us, ended_at_us "
            "FROM attempt WHERE task_id=? ORDER BY attempt_id", (task_id,))]
        decision = con.execute("SELECT action, reason_code FROM recovery_decision WHERE task_id=? ORDER BY decision_id DESC LIMIT 1",
                               (task_id,)).fetchone()
        now_us = int(time.time() * 1_000_000)
        open_auth = con.execute("SELECT COUNT(*) FROM authorization WHERE task_id=? AND superseded_at_us IS NULL "
                                "AND (valid_until_us IS NULL OR valid_until_us>?)", (task_id, now_us)).fetchone()[0]
        return {"task_id": task_id, "task": {"state": task["state"], "reason_code": task["reason_code"]}, "request": request,
                "attempts": attempts, "decision": dict(decision) if decision else None, "open_authorizations": open_auth}
    except sqlite3.Error as exc:
        return {"error": "LEDGER_QUERY_FAILED:" + type(exc).__name__}
    finally:
        con.close()


def journal_view(journal_path, operation_id):
    """Read-only view of the frozen client execution journal for one operation (= the supervisor task id)."""
    if not operation_id or not Path(journal_path).is_file():
        return None
    try:
        con = _ro(journal_path)
    except sqlite3.Error as exc:
        return {"error": "JOURNAL_UNREADABLE:" + type(exc).__name__}
    try:
        row = con.execute("SELECT state, receipt_digest IS NOT NULL AS receipted FROM operations WHERE id=?", (operation_id,)).fetchone()
        return {"operation_id": operation_id, "state": row["state"], "receipted": bool(row["receipted"])} if row else \
            {"operation_id": operation_id, "state": None}
    except sqlite3.Error as exc:
        return {"error": "JOURNAL_QUERY_FAILED:" + type(exc).__name__}
    finally:
        con.close()


_OP_ID = re.compile(r"^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$")


def corroborate(record, ledger, journal, server, task_exists=None, operation_owner=None):
    """The record's own `completed` is never reported on its own word (review round 1, OPS-1). A harness execution
    is `completed` only while the ledger says COMPLETE, the journal says `verified` and the server, when it answers,
    says `reply`; a local (no-task) execution only while the server answers `reply`. Anything less is reported as
    `uncertain` with the exact gap, the recorded state kept beside it. `server=None` means "not consulted" (listing);
    an unreachable server is a gap for a local execution and a non-contradiction for a harness one.
    -> (state, reason, corroboration dict)."""
    recorded = record.get("state")
    if recorded != "completed":
        return recorded, record.get("reason"), {"checked": False}
    gaps = []
    task_id = record.get("task_id")
    # Every execution (harness or local) ran under exactly one ticket operation; the worker claimed that operation for
    # this execution id when the ticket verified (create-once index). A record that names no operation, another
    # record's operation, or an operation this record never claimed is not corroborated (review round 4, OPS-1R).
    op = record.get("operation_id")
    if not isinstance(op, str) or not op:
        gaps.append("OPERATION_MISSING")
    else:
        owner = operation_owner(op) if operation_owner is not None else None
        if owner != record.get("execution_id"):
            gaps.append("OPERATION_NOT_OWNED")
        if task_id and task_id != op:
            gaps.append("OPERATION_TASK_MISMATCH")
        if isinstance(server, dict) and "error" not in server and server.get("operation_id") != op:
            gaps.append("SERVER_OPERATION_MISMATCH")
    if task_id:
        if not isinstance(ledger, dict) or (ledger.get("task") or {}).get("state") != "COMPLETE":
            gaps.append("LEDGER_NOT_COMPLETE")
        else:
            # The COMPLETE task must be THIS execution's: same turn, session, capability, selection and digests as the
            # record's proposal (a record pointing at another execution's finished task is not completed).
            req, prop = ledger.get("request") or {}, record.get("proposal") or {}
            if not isinstance(req, dict) or req.get("turn_id") != record.get("turn_id") or req.get("operation_id") != task_id \
                    or req.get("session_id") != record.get("session_id") \
                    or any(req.get(k) != prop.get(k) for k in ("session_id", "capability_id", "provider", "model",
                                                               "approval_digest", "argument_digest")):
                gaps.append("LEDGER_REQUEST_MISMATCH")
            # The ledger row names the ONE execution record the bridge ran for (review round 2, OPS-1R): a second
            # record copying every field of a genuine execution is still not that execution.
            if isinstance(req, dict) and req.get("execution_id") != record.get("execution_id"):
                gaps.append("LEDGER_EXECUTION_MISMATCH")
        if isinstance(server, dict) and "error" not in server:
            if server.get("state") != "reply":
                gaps.append("SERVER_TURN_NOT_REPLY")
            if server.get("session_id") != record.get("session_id"):
                gaps.append("SERVER_SESSION_MISMATCH")
    else:
        prop = record.get("proposal") or {}
        if prop.get("kind") == "client_external_harness":
            gaps.append("TASK_OMITTED")                   # a harness execution without its supervisor task (OPS-1R)
        if server is None or not isinstance(server, dict) or "error" in server:
            gaps.append("SERVER_UNAVAILABLE")
        else:
            if server.get("state") != "reply":
                gaps.append("SERVER_TURN_NOT_REPLY")
            if server.get("session_id") != record.get("session_id") or prop.get("session_id") != record.get("session_id"):
                gaps.append("SERVER_SESSION_MISMATCH")
            sop = server.get("operation_id")
            if sop and (task_exists(sop) if task_exists is not None else False):
                gaps.append("TASK_OMITTED")               # the server's operation IS a supervisor task: not local
    # The client journal (frozen C4) holds one row per ticket operation, local capabilities included.
    if not isinstance(journal, dict) or journal.get("state") != "verified":
        gaps.append("JOURNAL_NOT_VERIFIED")
    gaps = list(dict.fromkeys(gaps))
    if record.get("code") != "SETTLED_VERIFIED":
        gaps.append("CODE_NOT_SETTLED_VERIFIED")
    if gaps:
        return "uncertain", "UNCORROBORATED_COMPLETION:" + ",".join(gaps), {"checked": True, "gaps": gaps}
    return "completed", record.get("reason"), {"checked": True, "gaps": []}


_STR_OR_NONE = ("turn_id", "session_id", "request_text", "reason", "code", "message", "task_id", "bridge_outcome",
                "failure_category", "decision", "previous_state", "server_state", "operation_id", "operation_owner",
                "approval_retry_reason")
_NUM_OR_NONE = ("queued_at", "approving_at", "starting_at", "running_at", "ended_at", "updated_at", "cancel_requested_at", "worker_pid",
                "approval_retries")
_DICT_OR_NONE = ("proposal", "restart_ledger")
_LIST_OR_NONE = ("evidence",)


def _well_typed(rec, execution_id) -> bool:
    if not isinstance(rec, dict) or rec.get("schema") != SCHEMA or rec.get("execution_id") != execution_id:
        return False
    if not isinstance(rec.get("state"), str) or rec["state"] not in ACTIVE_STATES + TERMINAL_STATES:
        return False
    for k in _STR_OR_NONE:
        if k in rec and rec[k] is not None and not isinstance(rec[k], str):
            return False
    for k in _NUM_OR_NONE:
        if k in rec and rec[k] is not None and (isinstance(rec[k], bool) or not isinstance(rec[k], (int, float))):
            return False
    for k in _DICT_OR_NONE:
        if k in rec and rec[k] is not None and not isinstance(rec[k], dict):
            return False
    for k in _LIST_OR_NONE:
        if k in rec and rec[k] is not None and not isinstance(rec[k], list):
            return False
    if "cancel_requested" in rec and not isinstance(rec["cancel_requested"], bool):
        return False
    prop = rec.get("proposal")
    if isinstance(prop, dict):
        for k in ("proposal_digest", "approval_digest", "turn_id", "session_id", "kind", "provider", "model", "capability_id",
                  "argument_digest", "effect", "action", "instruction", "expected_file"):
            if k in prop and prop[k] is not None and not isinstance(prop[k], str):
                return False
        if not isinstance(prop.get("proposal_digest"), str):
            return False
        if "reversible" in prop and prop["reversible"] is not None and not isinstance(prop["reversible"], bool):
            return False
        for k in ("arguments", "qualification"):
            if k in prop and prop[k] is not None and not isinstance(prop[k], dict):
                return False
    ev = rec.get("evidence")
    if isinstance(ev, list):
        for e in ev:
            if not isinstance(e, dict):
                return False
            for k in ("check", "output_sha256", "harness", "supervisor_task", "basis"):
                if k in e and e[k] is not None and not isinstance(e[k], str):
                    return False
            for k in ("output_bytes", "supervisor_attempt"):
                if k in e and e[k] is not None and (isinstance(e[k], bool) or not isinstance(e[k], int)):
                    return False
            if "matched" in e and e["matched"] is not None and not isinstance(e["matched"], bool):
                return False
    return True


class ExecutionRegister:
    """Durable, worker-owned execution records. Atomic JSON per execution; never holds tickets, keys or tokens."""

    def __init__(self, client_root):
        self.root = Path(client_root).resolve()
        self.dir = self.root / "control" / "supervisor" / "executions"
        self.dir.mkdir(parents=True, exist_ok=True)
        self._lock = threading.RLock()

    def path(self, execution_id) -> Path:
        if not isinstance(execution_id, str) or not _ID.fullmatch(execution_id):
            raise TurnError("EXECUTION_ID_INVALID")
        return self.dir / (execution_id + ".json")

    # ---- operation ownership (review round 4, OPS-1R residual) -------------------------------------
    def _op_path(self, operation_id) -> Path | None:
        if not isinstance(operation_id, str) or not _OP_ID.fullmatch(operation_id):
            return None
        return self.dir / "operations" / (operation_id + ".json")

    def claim_operation(self, operation_id, execution_id):
        """First writer wins: the execution that verified the ticket for `operation_id` owns it for ever. Returns the
        owning execution id (this one, or an earlier claimant), or None when the id is not an operation id."""
        import json
        p = self._op_path(operation_id)
        if p is None:
            return None
        p.parent.mkdir(parents=True, exist_ok=True)
        with self._lock:
            try:
                with open(p, "x", encoding="utf-8") as f:
                    json.dump({"operation_id": operation_id, "execution_id": execution_id, "claimed_at": _now()}, f)
                    f.flush()
                    import os
                    os.fsync(f.fileno())
            except FileExistsError:
                pass
        return self.operation_owner(operation_id)

    def operation_owner(self, operation_id):
        import json
        p = self._op_path(operation_id)
        if p is None or not p.is_file():
            return None
        try:
            data = json.loads(p.read_text(encoding="utf-8"))
        except (OSError, ValueError):
            return None
        owner = data.get("execution_id") if isinstance(data, dict) else None
        return owner if isinstance(owner, str) and _ID.fullmatch(owner) and data.get("operation_id") == operation_id else None

    def get(self, execution_id):
        import json
        p = self.path(execution_id)
        with self._lock:
            if not p.is_file():
                return None
            try:
                rec = json.loads(p.read_text(encoding="utf-8"))
            except (OSError, ValueError):
                return {"schema": SCHEMA, "execution_id": execution_id, "state": "uncertain", "reason": "RECORD_UNREADABLE"}
        # Valid JSON is not yet a valid record (review round 1 OPS-2, round 2 OPS-2R): the id must be the file's and
        # every field the worker reads must have its type. Anything else is an uncertain stub, so listing and restart
        # reconciliation never abort on one damaged row.
        if not _well_typed(rec, execution_id):
            return {"schema": SCHEMA, "execution_id": execution_id, "state": "uncertain", "reason": "RECORD_SCHEMA"}
        return rec

    def write(self, record):
        with self._lock:
            atomic_json(self.path(record["execution_id"]), record)

    def update(self, execution_id, **fields):
        with self._lock:
            rec = self.get(execution_id)
            if rec is None:
                raise TurnError("EXECUTION_UNKNOWN")
            rec.update(fields)
            rec["updated_at"] = _now()
            self.write(rec)
            return rec

    def list(self, limit=_LIST_LIMIT):
        with self._lock:
            ids = sorted(p.stem for p in self.dir.glob("*.json") if _ID.fullmatch(p.stem))
            recs = [self.get(i) for i in ids]
        recs = [r for r in recs if r is not None]
        recs.sort(key=lambda r: (r.get("queued_at") or 0, r["execution_id"]), reverse=True)
        return recs[:limit]

    def reconcile_restart(self, ledger_path, why="WORKER_RESTARTED"):
        """Every non-terminal record belongs to a worker that is gone: the attempt (if any) was killed by its
        kill-on-close job and the bridge has revoked the task's authority. The record becomes `uncertain`; the ledger
        facts are attached. Nothing is re-launched."""
        out = []
        for rec in self.list(limit=10_000):
            if rec.get("state") in TERMINAL_STATES:
                continue
            view = ledger_view(ledger_path, rec.get("task_id"))
            self.update(rec["execution_id"], state="uncertain", reason=why, ended_at=_now(), restart_ledger=view,
                        previous_state=rec.get("state"))
            out.append({"execution_id": rec["execution_id"], "was": rec.get("state"), "state": "uncertain", "reason": why})
        return out


class ExecutionController:
    """Worker-side lifecycle driver. `service` is the SupervisedWorkerService that owns the pending turns and the
    runner; `bridge` the SupervisorBridge whose `cancel` kills running attempts."""

    def __init__(self, service, client_root, *, bridge, composition=None, server_status=None, clock=None):
        self.service, self.bridge, self.composition = service, bridge, composition
        self.clock = clock or _now
        self.root = Path(client_root).resolve()
        self.register = ExecutionRegister(self.root)
        self.ledger_path = self.root / "control" / "supervisor" / "ledger.db"
        self.journal_path = self.root / "control" / "execution-journal.sqlite3"
        self._server_status = server_status
        self._lock = threading.Lock()
        self._active = None
        self._thread = None
        self._cancel = set()
        self._task = {}
        self.startup = self._reconcile_on_start()

    # ---- start-up -----------------------------------------------------------------------------
    def _reconcile_on_start(self):
        journal = None
        if self.journal_path.is_file():
            try:
                # Frozen rule (C4 journal): after a restart every claimed operation is uncertain until reconciled.
                journal = [o for o in ExecutionJournal(self.root).recover() if o["state"] == "execution_uncertain"]
            except Exception as exc:  # noqa: BLE001  (reported, never hidden; the register still reconciles)
                journal = {"error": "JOURNAL_RECOVER_FAILED:" + type(exc).__name__}
        return {"journal": journal, "executions": self.register.reconcile_restart(self.ledger_path)}

    # ---- queries ------------------------------------------------------------------------------
    @property
    def active(self):
        with self._lock:
            return self._active

    def qualification_of(self, provider, kind="client_external_harness"):
        """Qualification row for a harness provider; None for non-harness rows (the deterministic local row)."""
        if self.composition is None or not provider or kind != "client_external_harness":
            return None
        for row in self.composition.report:
            if row.get("provider") == provider:
                keys = ("status", "reason", "level", "models", "version", "expires_at", "qualified_at", "executable_sha256")
                return {k: row.get(k) for k in keys}
        return {"status": "NOT_QUALIFIED", "reason": "NO_RECORD"}

    def proposal(self, turn_id):
        entry = self.service.pending.get(turn_id)
        if entry is None:
            raise TurnError("TURN_NOT_PENDING")
        _, session, reasoning, turn = entry
        return execution_proposal(self.service.manifest.data["client_id"], session, turn_id, reasoning,
                                  turn.get("approval_request"), self.qualification_of(reasoning.get("provider"), reasoning.get("kind")))

    def status(self, execution_id):
        rec = self.register.get(execution_id)
        if rec is None:
            raise TurnError("EXECUTION_UNKNOWN")
        task_id, op = rec.get("task_id"), rec.get("operation_id")
        ledger, journal = ledger_view(self.ledger_path, task_id), journal_view(self.journal_path, op if isinstance(op, str) else task_id)
        server = self._server_turn(rec.get("turn_id"))
        state, reason, corroboration = corroborate(rec, ledger, journal, server, self._task_exists, self.register.operation_owner)
        return {**rec, "state": state, "reason": reason, "recorded_state": rec.get("state"), "corroboration": corroboration,
                "operation_owner": self.register.operation_owner(op) if isinstance(op, str) else None,
                "ledger": ledger, "journal": journal, "server_turn": server}

    def list(self):
        out = []
        for r in self.register.list():
            state, reason = r.get("state"), r.get("reason")
            corroboration = {"checked": False}
            if state == "completed":
                # A listed success is held to exactly the same facts as a status (review rounds 1-2, OPS-1/OPS-1R).
                task_id, op = r.get("task_id"), r.get("operation_id")
                ledger, journal = ledger_view(self.ledger_path, task_id), journal_view(self.journal_path, op if isinstance(op, str) else task_id)
                state, reason, corroboration = corroborate(r, ledger, journal, self._server_turn(r.get("turn_id")), self._task_exists,
                                                           self.register.operation_owner)
            out.append({k: r.get(k) for k in ("execution_id", "turn_id", "session_id", "code", "queued_at", "ended_at",
                                                 "task_id", "cancel_requested")}
                       | {"state": state, "reason": reason, "recorded_state": r.get("state"), "corroboration": corroboration,
                          "provider": (r.get("proposal") or {}).get("provider"), "model": (r.get("proposal") or {}).get("model")})
        return out

    def _task_exists(self, operation_id):
        view = ledger_view(self.ledger_path, operation_id)
        return isinstance(view, dict) and view.get("task") is not None

    def _server_turn(self, turn_id):
        if not turn_id:
            return None
        try:
            if self._server_status is not None:
                data = self._server_status(turn_id)
            else:
                data = self.service.transport.request("GET", f"/client/v1/turns/{turn_id}/status", None)
            return {k: data.get(k) for k in ("state", "version", "operation_id", "session_id")} if isinstance(data, dict) else {"error": "BAD_STATUS"}
        except Exception as exc:  # noqa: BLE001  (the server view is informative; unreachable = reported, not invented)
            return {"error": "SERVER_STATUS_UNAVAILABLE:" + str(getattr(exc, "code", type(exc).__name__))[:64]}

    # ---- begin ----------------------------------------------------------------------------------
    def begin(self, turn_id, approval_digest, proposal_digest):
        with self._lock:
            if self._active is not None:
                raise TurnError("EXECUTION_IN_PROGRESS")
            entry = self.service.pending.get(turn_id)
            if entry is None or not isinstance(turn_id, str):
                raise TurnError("TURN_NOT_PENDING")
            text, session, reasoning, turn = entry
            prop = execution_proposal(self.service.manifest.data["client_id"], session, turn_id, reasoning,
                                      turn.get("approval_request"), self.qualification_of(reasoning.get("provider"), reasoning.get("kind")))
            shown = (turn.get("approval_request") or {}).get("approval_digest")
            if not isinstance(approval_digest, str) or approval_digest != shown:
                self.service.pending.pop(turn_id, None)        # same rule as turn_decide: a wrong echo drops the turn
                self._release(entry, "APPROVAL_DIGEST_MISMATCH")
                raise TurnError("APPROVAL_DIGEST_MISMATCH")
            if not isinstance(proposal_digest, str) or proposal_digest != prop["proposal_digest"]:
                self.service.pending.pop(turn_id, None)
                self._release(entry, "PROPOSAL_DIGEST_MISMATCH")
                raise TurnError("PROPOSAL_DIGEST_MISMATCH")
            self.service.pending.pop(turn_id, None)
            eid = uuid.uuid4().hex
            rec = {"schema": SCHEMA, "execution_id": eid, "turn_id": turn_id, "session_id": session, "request_text": text,
                   "proposal": prop, "state": "queued", "reason": None, "code": None, "message": None, "task_id": None,
                   "bridge_outcome": None, "failure_category": None, "evidence": None, "cancel_requested": False,
                   "operation_id": None, "operation_owner": None,
                   "queued_at": self.clock(), "approving_at": None, "starting_at": None, "running_at": None, "ended_at": None,
                   "worker_pid": None}
            import os
            rec["worker_pid"] = os.getpid()
            self.register.write(rec)
            self._active = eid
            self._thread = threading.Thread(target=self._run, args=(eid, text, session, reasoning, turn), daemon=True,
                                            name="uri-execution-" + eid[:8])
            self._thread.start()
        return {"execution_id": eid, "turn_id": turn_id, "state": "queued", "proposal_digest": prop["proposal_digest"]}

    def _release(self, entry, why):
        """CAP-1: the turn this worker just abandoned is released on the server (see worker_service)."""
        release = getattr(self.service, "release_turn", None)
        return release(entry, why) if release is not None else None

    def _cancel_requested(self, eid):
        with self._lock:
            return eid in self._cancel

    def _run(self, eid, text, session, reasoning, turn):
        runner = None
        try:
            runner = self.service._runner()
            approve = not self._cancel_requested(eid)
            self.register.update(eid, state="approving", approving_at=self.clock(), decision="approve" if approve else "deny")

            def on_dispatch(work):
                with self._lock:
                    self._task[eid] = work.task_id
                    cancelled = eid in self._cancel
                self.register.update(eid, task_id=work.task_id, state="running", running_at=self.clock())
                if cancelled:
                    self.bridge.cancel(work.task_id)          # arrived between approval and dispatch: never spawns

            def on_outcome(work, outcome, evidence, failure):
                public = [{k: e.get(k) for k in ("check", "matched", "output_sha256", "output_bytes", "harness",
                                                  "supervisor_task", "supervisor_attempt", "basis")}
                          for e in (evidence or []) if isinstance(e, dict)]
                self.register.update(eid, bridge_outcome=outcome, failure_category=failure, evidence=public)

            def on_starting(operation_id):
                owner = self.register.claim_operation(operation_id, eid)      # create-once: first execution wins
                self.register.update(eid, state="starting", starting_at=self.clock(), operation_id=operation_id, operation_owner=owner)

            runner.on_dispatch, runner.on_outcome, runner.on_starting = on_dispatch, on_outcome, on_starting
            runner.dispatch_context = {"execution_id": eid}       # the bridge records it in the ledger task row
            final = self._decide(eid, runner, text, session, reasoning, turn, approve)
            rec = self.register.get(eid)
            state, reason = self._classify(final, rec, approve)
            self.register.update(eid, state=state, reason=reason, code=final.get("code"), message=final.get("message"),
                                 server_state=final.get("state"), ended_at=self.clock())
        except Exception as exc:  # noqa: BLE001
            code = str(getattr(exc, "code", type(exc).__name__))[:96]
            rec = self.register.get(eid) or {}
            # Nothing was sent to the server while `queued`; afterwards the approval, claim or settle may have landed,
            # unless the server itself shows the turn still awaiting approval at the version we approved (VAL-1).
            if rec.get("state") == "queued":
                state, reason = "failed", "EXCEPTION:" + code
            elif self._approval_provably_unapplied(rec, turn, session):
                state, reason = "failed", "APPROVAL_REFUSED_NOT_APPLIED:" + code
                self._release((text, session, reasoning, turn), "APPROVAL_REFUSED_NOT_APPLIED")   # CAP-1
            else:
                state, reason = "uncertain", "EXCEPTION:" + code
            self.register.update(eid, state=state, reason=reason, ended_at=self.clock())
        finally:
            if runner is not None:
                runner.on_dispatch = runner.on_outcome = runner.on_starting = runner.dispatch_context = None
            with self._lock:
                if self._active == eid:
                    self._active = None
                self._task.pop(eid, None)
                self._cancel.discard(eid)

    # ---- VAL-1: the frozen ticket clock boundary --------------------------------------------------
    # The frozen coordinator stamps `issued_at = int(clock())` and the frozen control refuses the ticket unless the
    # same whole second is read again after the authority callback (`client_execution_control.py:77`); crossing a
    # second boundary in between is `TICKET_CLOCK_OR_GENERATION`, re-raised as HTTP 403 BEFORE any version bump,
    # idempotency record or operation write (`paired_coordinator.py:314-316`, `client_service.py:256-261`).
    # `tests/phase2ops/test_val1_clock_boundary.py` reproduces it. The worker may resend the user's SAME approval once,
    # and only when nothing can have been applied: no ticket observed, no task, no cancel, and the server's own turn
    # status is still `approval_required` at the version and session the approval was built for. Every server gate
    # runs again on the resend; a second refusal ends the execution `failed` (nothing ran), never `uncertain`.
    APPROVAL_RETRY_CODES = ("SERVER_REFUSED:HTTP_403", "SERVER_REFUSED:TICKET_CLOCK_OR_GENERATION")

    def _approval_provably_unapplied(self, rec, turn, session):
        if not isinstance(rec, dict) or rec.get("state") != "approving":
            return False
        if rec.get("operation_id") or rec.get("task_id") or rec.get("starting_at") or rec.get("running_at"):
            return False
        server = self._server_turn(turn.get("turn_id")) or {}
        return (server.get("state") == "approval_required" and type(server.get("version")) is int
                and server.get("version") == turn.get("version") and server.get("session_id") in (None, session))

    def _decide(self, eid, runner, text, session, reasoning, turn, approve):
        try:
            return runner.decide(text, session, reasoning, turn, approve)
        except TurnError as exc:
            code = str(getattr(exc, "code", ""))
            if (not approve or code not in self.APPROVAL_RETRY_CODES or self._cancel_requested(eid)
                    or not self._approval_provably_unapplied(self.register.get(eid), turn, session)):
                raise
            self.register.update(eid, approval_retries=1, approval_retry_reason=code[:96])
        return runner.decide(text, session, reasoning, turn, approve)

    @staticmethod
    def _classify(final, rec, approve):
        code = final.get("code") if isinstance(final, dict) else None
        failure = (rec or {}).get("failure_category") or ""
        cancel = bool((rec or {}).get("cancel_requested")) or not approve
        if code == "SETTLED_VERIFIED":
            return "completed", None
        if code == "APPROVAL_DENIED":
            return "cancelled", "CANCELLED_BEFORE_APPROVAL" if cancel else "DECLINED"
        if code == "WAITING_FOR_MODEL":
            return "quota_paused", "PROVIDER_QUOTA_EXHAUSTED"
        if code == "SETTLED_EXECUTION_UNCERTAIN":
            return "uncertain", ("CANCELLED_AFTER_DISPATCH" if cancel and failure.startswith("CANCELLED_AFTER_DISPATCH") else failure or code)
        if code == "SETTLED_FAILED":
            if cancel and failure == NOT_STARTED + "CANCELLED":
                return "cancelled", "CANCELLED_BEFORE_START"
            return "failed", failure or code
        return "uncertain", "UNRECOGNISED_SETTLEMENT:" + str(code)[:64]

    # ---- cancel ----------------------------------------------------------------------------------
    def cancel(self, execution_id):
        with self._lock:
            rec = self.register.get(execution_id)
            if rec is None:
                raise TurnError("EXECUTION_UNKNOWN")
            if rec.get("state") in TERMINAL_STATES:
                raise TurnError("EXECUTION_TERMINAL")
            if self._active != execution_id:
                raise TurnError("EXECUTION_NOT_OWNED")       # a record from an earlier worker; restart reconciliation owns it
            self._cancel.add(execution_id)
            task = self._task.get(execution_id)
        self.register.update(execution_id, cancel_requested=True, cancel_requested_at=self.clock())
        kill = self.bridge.cancel(task)["kill"] if task else {"granted": False, "reason": "NOT_DISPATCHED"}
        return {"execution_id": execution_id, "cancel": "requested", "kill": kill, "state": self.register.get(execution_id)["state"]}

    # ---- shutdown ---------------------------------------------------------------------------------
    def close(self, timeout_s=30.0):
        """The owning worker is going away: withdraw the active execution (kill through the job) and wait, bounded,
        for its settlement so the record is terminal. The kill-on-close job covers whatever is left."""
        eid = self.active
        if eid is None:
            return {"active": None}
        try:
            self.cancel(eid)
        except TurnError as exc:
            return {"active": eid, "cancel": str(exc.code)}
        t = self._thread
        if t is not None:
            t.join(timeout_s)
        rec = self.register.get(eid) or {}
        if rec.get("state") not in TERMINAL_STATES:
            self.register.update(eid, state="uncertain", reason="WORKER_CLOSED_DURING_EXECUTION", ended_at=self.clock())
        return {"active": eid, "state": self.register.get(eid)["state"]}
"""Phase 2D worker-side service: the frozen worker protocol, served by the SupervisedTurnRunner.

Same commands and envelopes as the frozen `TurnService` (`turn_start`, `turn_intent`, `turn_decide`), so the
frozen UI client (`uri_ui/lib/services/paired_runtime.dart`) could drive it unchanged, plus strict additions:

  * `turn_decide` MAY carry `approval_digest`: when present it must equal the digest of the approval request the
    worker showed for that turn; a mismatch drops the pending turn and refuses (`APPROVAL_DIGEST_MISMATCH`). A UI
    that echoes the digest it displayed therefore cannot approve a turn whose arguments changed underneath it. The
    worker still binds the approval to its own pending record either way (UI is never the authority).
  * `turn_cancel {turn_id}`: explicit withdrawal of a pending (not yet dispatched) turn. It is sent to the server as
    a denial, so nothing is ever executed for it.
  * Phase 2 UI/operations (`execution.py`): an `approval_required` reply also carries `execution_proposal`;
    `execution_begin {turn_id, approval_digest, proposal_digest}` approves and dispatches in a worker thread and
    returns at once with an `execution_id`; `execution_status {execution_id}`, `execution_cancel {execution_id}` and
    `execution_list {}` read and withdraw that execution while the frame loop stays responsive. While an execution is
    in flight every turn command is refused with `EXECUTION_IN_PROGRESS` (one execution per client at a time).
    `turn_decide` (blocking, frozen semantics) remains available and cannot be cancelled mid-run.

Phase 2 closure, CAP-1: the frozen server lets each (client, session) hold ONE active turn and the whole server FOUR
(`client_service.py:169-174`), and an `approval_required` turn that nobody decides stays active for 15 minutes idle.
Whenever this worker abandons a pending turn on its own (a wrong digest echo, or `close`/stdin EOF with turns still
pending) it now releases it through the frozen server's own cancel route (`POST /client/v1/turns/{id}/cancel`,
version-checked; the server never relabels a dispatched turn). Before this, four abandoned cards blocked every new
turn on the server for up to 15 minutes. A worker that dies without `close` still cannot release (pending state is
memory-only); the server's 15-minute expiry remains the backstop.

Pending state is memory-only, exactly as in the frozen service: a worker restart or reconnect drops every pending
turn (fail closed, `TURN_NOT_PENDING`), and the frozen server's own guards (`INTENT_EXECUTION_UNCERTAIN`,
`INTENT_ALREADY_EXECUTED`, duplicate operation ids) prevent a second execution of the same work. Execution records
(`control/supervisor/executions/`) are durable and are reconciled, never replayed, at the next start.
"""
from __future__ import annotations

from uri_core.client_runtime.turn_runner import TurnError

from .execution import ExecutionController
from .runner import SupervisedTurnService

COMMAND_SCHEMAS = {
    "turn_start": ({"command", "session_id", "text", "reasoning"},),
    "turn_intent": ({"command", "session_id", "text", "reasoning", "intent_decision"},),
    "turn_decide": ({"command", "turn_id", "approve"}, {"command", "turn_id", "approve", "approval_digest"}),
    "turn_cancel": ({"command", "turn_id"},),
    "execution_begin": ({"command", "turn_id", "approval_digest", "proposal_digest"},),
    "execution_status": ({"command", "execution_id"},),
    "execution_cancel": ({"command", "execution_id"},),
    "execution_list": ({"command"},),
}
EXECUTION_COMMANDS = ("execution_begin", "execution_status", "execution_cancel", "execution_list")
TURN_COMMANDS = ("turn_start", "turn_intent", "turn_decide", "turn_cancel")


class SupervisedWorkerService(SupervisedTurnService):
    def __init__(self, manifest, persistence, bridge, harness=None, composition=None, executions=True, server_status=None, clock=None):
        super().__init__(manifest, persistence, bridge, harness=harness)
        self.composition = composition
        self.executions = ExecutionController(self, manifest.data["client_root"], bridge=bridge, composition=composition,
                                              server_status=server_status, clock=clock) if executions else None
        self.released = []      # last releases (CAP-1), for diagnostics only: ids, codes, never content

    def release_turn(self, entry, why):
        """CAP-1: release an abandoned, never-dispatched `approval_required` turn on the server. Best effort, never
        raises: a refusal (`VERSION_CONFLICT`, `TURN_TERMINAL`, unreachable server) is recorded and the server's own
        expiry stays the backstop. Nothing is approved, denied or executed by it."""
        turn_id = None
        try:
            text, session, reasoning, turn = entry
            turn_id = turn.get("turn_id")
            runner = self._runner()
            status, data = runner.call("POST", f"/client/v1/turns/{turn_id}/cancel", runner._control(session, turn))
            state = data.get("state") if isinstance(data, dict) else None
            detail = data.get("detail") if isinstance(data, dict) else None
            out = {"turn_id": turn_id, "why": why, "released": status == 200 and state == "cancelled",
                   "status": status, "server_state": state if isinstance(state, str) else None,
                   "code": detail[:64] if isinstance(detail, str) else None}
        except Exception as exc:  # noqa: BLE001  (best effort; reported, never hidden)
            out = {"turn_id": turn_id, "why": why, "released": False, "error": type(exc).__name__}
        self.released = (self.released + [out])[-20:]
        return out

    def release_pending(self, why="WORKER_CLOSED"):
        """Release every turn still pending in this worker (close / stdin EOF)."""
        entries = [self.pending.pop(t, None) for t in list(self.pending)]
        return [self.release_turn(entry, why) for entry in entries if entry is not None]

    @property
    def execution_active(self):
        return self.executions.active if self.executions is not None else None

    def handle(self, kind, command):
        shapes = COMMAND_SCHEMAS.get(kind)
        if shapes is None or set(command) not in shapes:
            raise TurnError("COMMAND_SCHEMA")
        if kind in EXECUTION_COMMANDS:
            if self.executions is None:
                raise TurnError("EXECUTION_NOT_AVAILABLE")
            if kind == "execution_begin":
                return self.executions.begin(command["turn_id"], command["approval_digest"], command["proposal_digest"])
            if kind == "execution_status":
                return self.executions.status(command["execution_id"])
            if kind == "execution_cancel":
                return self.executions.cancel(command["execution_id"])
            return {"executions": self.executions.list(), "active": self.executions.active, "startup": self.executions.startup}
        if self.execution_active is not None:
            raise TurnError("EXECUTION_IN_PROGRESS")
        if kind == "turn_cancel":
            entry = self.pending.pop(command["turn_id"], None)
            if entry is None:
                raise TurnError("TURN_NOT_PENDING")
            text, session, reasoning, turn = entry
            return self._public(self._runner().decide(text, session, reasoning, turn, False))
        if kind == "turn_decide":
            turn_id = command["turn_id"]
            if not isinstance(turn_id, str) or not isinstance(command["approve"], bool):
                dropped = self.pending.pop(turn_id, None) if isinstance(turn_id, str) else None
                if dropped is not None:
                    self.release_turn(dropped, "DECIDE_SCHEMA")
                raise TurnError("TURN_NOT_PENDING")
            if "approval_digest" in command:
                entry = self.pending.get(turn_id)
                shown = ((entry[3].get("approval_request") or {}).get("approval_digest")) if entry else None
                if entry is None or not isinstance(command["approval_digest"], str) or command["approval_digest"] != shown:
                    if self.pending.pop(turn_id, None) is not None:
                        self.release_turn(entry, "APPROVAL_DIGEST_MISMATCH")
                    raise TurnError("APPROVAL_DIGEST_MISMATCH" if entry is not None else "TURN_NOT_PENDING")
                command = {k: v for k, v in command.items() if k != "approval_digest"}
        result = super().handle(kind, command)
        if kind in ("turn_start", "turn_intent") and result.get("state") == "approval_required" and self.executions is not None:
            result["execution_proposal"] = self.executions.proposal(result["turn_id"])
        return result

"""Phase 2 server PROFILE diagnostic (UI/operations slice, review rounds 3-5: VAL-1, LOG-1).

An intermittent HTTP 403 on a `/client/v1` request could not be attributed because the frozen client transport keeps
the status only. This pure-ASGI wrapper logs, for `/client/v1` responses with status >= 400 ONLY, a line of the form

    CLIENT_REFUSAL <METHOD> <route shape> <status> <CODE>

where the route shape is the request path with every segment that is not a known literal replaced by `{id}` and the
CODE is the JSON body's `detail` only when it is one of the frozen server's known refusal codes (`KNOWN_CODES`); any
other detail is logged as `OTHER_CODE`, and any method other than GET/POST as `OTHER_METHOD`. Query strings, request headers, request bodies, 2xx bodies and free text are
never read into the log (review round 5, LOG-1: an earlier version printed the raw path and detail).
"""
from __future__ import annotations

import json
import sys

# Allow-list (review round 6, LOG-1R): exactly the refusal codes the frozen paired server emits on /client/v1, extracted
# verbatim from uri_core/app/client_routes.py, core/client_service.py, core/client_pairing.py,
# core/client_execution_control.py, core/client_state_ports.py and core/paired_coordinator.py (ClientControlError / PairingError /
# ExecutionControlError / StatePortError / HTTPException details). Anything else, uppercase or not, logs as OTHER_CODE.
KNOWN_CODES = frozenset("""
APPROVAL_DIGEST_MISMATCH AUTHENTICATION_REQUIRED BASE_VERSION_REQUIRED CANONICAL_COMPOSITION_PENDING
CLAIM_ALREADY_SETTLED_OR_UNCERTAIN CLAIM_SCHEMA CLIENT_ALREADY_PAIRED CLIENT_BINDING CLIENT_BINDING_REQUIRED
CLIENT_INVALID CLIENT_SCHEMA_INVALID CLIENT_UNKNOWN CONTEXT_REQUIRED_AFTER_RESTART CONTEXT_SCOPE
CONTROL_STORE_UNAVAILABLE DUPLICATE_ARGUMENT EXECUTION_AUTHORITY_UNAVAILABLE EXECUTION_CONTROL_UNAVAILABLE
EXECUTION_SCOPE EXECUTION_TERMINAL EXECUTION_VERSION_CONFLICT IDEMPOTENCY_CONFLICT METHOD_NOT_ALLOWED
OPERATION_ALREADY_PREPARED PAIRED_COMPOSITION_REQUIRED PAIRING_INVALID PAIRING_REQUIRED PAIRING_REVOKED
PAIRING_STORE_UNAVAILABLE PREVIOUS_PROJECTION_DIGEST PRINCIPAL_BINDING PRINCIPAL_INVALID PRINCIPAL_SCOPE
PRINCIPAL_SESSION_INVALID PROVIDER_CHECKPOINT_SCHEMA RECEIPT_CANCEL_AFTER_DISPATCH RECEIPT_CONFLICT
RECEIPT_SCOPE RECEIPT_VERIFIER_UNAVAILABLE RECEIPT_WITHOUT_CLAIM REQUEST_BINDING REQUEST_LIMIT SERVER_BINDING
SESSION_EXPIRED SESSION_INVALID SESSION_REPLACEMENT_SCOPE SESSION_SCOPE TICKET_CLOCK_OR_GENERATION
TICKET_EXPIRED_OR_RESTARTED TICKET_REFUSED TICKET_UNKNOWN TURN_CAPACITY TURN_NOT_AWAITING_APPROVAL
TURN_NOT_CLAIMABLE TURN_NOT_CONTINUABLE TURN_NOT_SETTLEABLE TURN_NOT_WAITABLE TURN_SCOPE TURN_TERMINAL
TURN_UNKNOWN VERSION_CONFLICT
""".split())
KNOWN_METHODS = frozenset({"GET", "POST"})
BODY_CAP = 4096   # bytes of an error body ever retained for the code lookup (LOG-3)
_LITERALS = frozenset({"client", "v1", "turns", "session", "capabilities", "approval", "claim", "settle", "wait",
                       "continue", "status", "cancel"})


def route_shape(path) -> str:
    """`/client/v1/turns/<uuid>/approval` -> `/client/v1/turns/{id}/approval`; never echoes a non-literal segment."""
    if not isinstance(path, str):
        return "/{invalid}"
    parts = [p for p in path.split("?", 1)[0].split("/") if p]
    out = [p if p in _LITERALS else "{id}" for p in parts][:8]
    return "/" + "/".join(out)


def refusal_code(body: bytes) -> str:
    try:
        detail = json.loads(body).get("detail")
    except Exception:  # noqa: BLE001  (non-JSON or non-object body)
        return "NON_JSON_BODY"
    return detail if isinstance(detail, str) and detail in KNOWN_CODES else "OTHER_CODE"


def in_scope(path) -> bool:
    """Exactly `/client/v1` or a path below it (review round 6, LOG-2: `/client/v1evil` is outside)."""
    return isinstance(path, str) and (path == "/client/v1" or path.startswith("/client/v1/"))


def refusal_line(method, path, status, body) -> str:
    m = method if isinstance(method, str) and method in KNOWN_METHODS else "OTHER_METHOD"
    try:
        st = int(status) if 100 <= int(status) <= 599 else 0
    except (TypeError, ValueError):
        st = 0
    return f"CLIENT_REFUSAL {m} {route_shape(path)} {st} {refusal_code(body)}"


class RefusalLog:
    def __init__(self, app, sink=None):
        self.app = app
        self.sink = sink or (lambda line: print(line, file=sys.stderr, flush=True))

    async def __call__(self, scope, receive, send):
        if scope.get("type") != "http" or not in_scope(scope.get("path")):
            return await self.app(scope, receive, send)
        # LOG-3 (Codex round 7, Low): retain at most BODY_CAP bytes of an error body, whatever its size or chunking;
        # the earlier version kept every chunk and truncated only after joining them.
        status, kept = [None], bytearray()

        async def send_wrapped(message):
            if message["type"] == "http.response.start":
                status[0] = message.get("status")
            elif message["type"] == "http.response.body" and status[0] is not None and status[0] >= 400:
                room = BODY_CAP - len(kept)
                if room > 0:
                    body = message.get("body", b"")
                    kept.extend(body[:room] if isinstance(body, (bytes, bytearray)) else b"")
                if not message.get("more_body"):
                    self.sink(refusal_line(scope.get("method"), scope.get("path"), status[0], bytes(kept)))
            await send(message)
        await self.app(scope, receive, send_wrapped)
"""Phase 2D: persisted, evidence-backed executor qualification for the client-side composition (schema v2).

A qualification record says: THIS client (client_id + its Ed25519 public key) qualified THIS provider, run as THIS
launch chain (executable file + every pinned file the launcher executes, each with SHA-256) at THIS reported version,
for THESE models, at THIS level, on the strength of THIS evidence file, until THIS expiry. It lives in the client's own
state root (`<client_root>/control/supervisor/qualification/<provider>.json`, evidence under `.../qualification/evidence/`)
and is re-validated on every load:

  * signature: Ed25519 by the client's own key over the canonical record (independent review round 1, D1/D3: an
    unkeyed digest could be recomputed after editing `models`; an unbound record could be copied to another client);
  * binding: `client_id` and `client_public_key` must equal the composing client's manifest values;
  * expiry: `expires_at` (epoch seconds) must lie in the future;
  * evidence: the client-owned evidence file must still hash to `evidence_sha256` AND its content must agree with the
    record (provider, success, version, executable hash) (review D2: the evidence was never re-read);
  * launch chain: the executable and every `pinned_files` entry must still hash as recorded, and every `resolve_pins`
    name (for example `node` for the npm shim) must still resolve, on the executor PATH, to the pinned file (review D4:
    only the `.cmd` shim was pinned, not the program it launches);
  * `--version` must still report the recorded version; `FIXTURE_ONLY` only when the composition allows fixtures.

Anything that fails leaves the provider where the frozen Phase 1 registry leaves it by default: `NATIVE_UNQUALIFIED`,
not usable. Authentication is never persisted: it is probed live on every registry decision (`codex login status`,
`claude auth status`) under the executor's environment allow-list, never by reading a credential file or logging in.

Trust limit (stated, not hidden): the signing key is the client key protected by current-user DPAPI (Phase 1 C1:
same-user logical isolation only). A process running as the same Windows user can sign. The record defends against
hand edits, copies between clients, stale evidence and launcher/payload replacement, not against same-user malware.
"""
from __future__ import annotations

import hashlib
import json
import os
import re
import shutil
import subprocess
import time
import uuid
from dataclasses import dataclass, replace
from pathlib import Path

from cryptography.exceptions import InvalidSignature
from cryptography.hazmat.primitives import serialization
from cryptography.hazmat.primitives.asymmetric.ed25519 import Ed25519PrivateKey, Ed25519PublicKey

from uri_core.client_runtime.harness import HarnessRegistry, harness_env, probe_version, resolve_command
from uri_supervisor.executors import BUILTIN_SPECS, GENERIC_NDJSON, ExecutorSpec

from .bridge import ExecutorBinding, _file_sha256, _same_file

SCHEMA = "uri.phase2d.qualification.v2"
LEVELS = ("NATIVE_QUALIFIED", "FIXTURE_ONLY")
DEFAULT_TTL_S = 30 * 24 * 3600
MAX_TTL_S = 90 * 24 * 3600
_PROVIDER = re.compile(r"^[a-z][a-z0-9_]{0,63}$")
_MODEL = re.compile(r"^[A-Za-z0-9][A-Za-z0-9._:/-]{0,127}$")
_HEX64 = re.compile(r"^[0-9a-f]{64}$")
_UUID = re.compile(r"^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$")
_EVIDENCE_NAME = re.compile(r"^[a-z][a-z0-9_]{0,63}-[0-9a-f]{16}\.json$")
_RESOLVE_NAME = re.compile(r"^[A-Za-z0-9][A-Za-z0-9._-]{0,63}$")
REQUIRED = ("schema", "provider", "level", "spec_id", "client_id", "client_public_key", "executable", "executable_args",
            "executable_sha256", "pinned_files", "resolve_pins", "version", "models", "evidence_file", "evidence_sha256",
            "qualified_at", "expires_at", "qualified_by", "record_sha256", "signature")
OPTIONAL = ("notes",)
# Live, read-only authentication status commands.
AUTH_STATUS_ARGV = {"codex_cli": ("login", "status"), "claude_code": ("auth", "status")}
AUTH_VARS = {"claude_code": ("CLAUDE_CODE_OAUTH_TOKEN",), "codex_cli": ("CODEX_API_KEY", "CODEX_HOME")}


class QualificationError(ValueError):
    def __init__(self, code, detail=None):
        super().__init__(code if detail is None else f"{code}: {detail}")
        self.code, self.detail = code, detail


@dataclass(frozen=True)
class RecordTrust:
    """The composing client's identity: records must be bound to it and signed by its key."""
    client_id: str
    public_key_hex: str

    @staticmethod
    def from_manifest(data: dict) -> "RecordTrust":
        return RecordTrust(data["client_id"], data["client_public_key"])

    @staticmethod
    def from_private_key(client_id, key: Ed25519PrivateKey) -> "RecordTrust":
        return RecordTrust(client_id, _public_hex(key))


def _public_hex(key: Ed25519PrivateKey) -> str:
    return key.public_key().public_bytes(serialization.Encoding.Raw, serialization.PublicFormat.Raw).hex()


def qualification_dir(client_root) -> Path:
    return Path(client_root).resolve() / "control" / "supervisor" / "qualification"


def evidence_dir(client_root) -> Path:
    return qualification_dir(client_root) / "evidence"


def _canonical(record: dict) -> bytes:
    return json.dumps({k: v for k, v in record.items() if k not in ("record_sha256", "signature")}, sort_keys=True,
                      separators=(",", ":"), ensure_ascii=True).encode("utf-8")


def record_digest(record: dict) -> str:
    return hashlib.sha256(_canonical(record)).hexdigest()


# ---- launch chain discovery --------------------------------------------------------------------------------------

def executor_path(environ=None) -> str:
    """The PATH the supervisor forwards to executors (same allow-list as `ExecutorSpec.build_env`)."""
    env = environ if environ is not None else os.environ
    return env.get("PATH", "")


def npm_codex_launch_chain(shim, environ=None):
    """For the npm `codex.cmd` launcher: every file the launch executes or loads by name, and the `node` resolution.
    Returns (pinned_files {abs path: sha256}, resolve_pins {name: abs path}). Raises QualificationError if the chain
    cannot be established (unknown layout = no native qualification)."""
    shim = Path(shim).resolve()
    dp0 = shim.parent
    pinned, resolve = {}, {}
    local_node = dp0 / "node.exe"
    if local_node.is_file():
        node = local_node.resolve()
    else:
        found = shutil.which("node", path=executor_path(environ))
        if not found:
            raise QualificationError("LAUNCH_CHAIN_NODE_UNRESOLVED")
        node = Path(found).resolve()
        resolve["node"] = str(node)
    pkg = dp0 / "node_modules" / "@openai" / "codex"
    entry = pkg / "bin" / "codex.js"
    if not entry.is_file():
        raise QualificationError("LAUNCH_CHAIN_ENTRY_MISSING")
    platform_pkg = pkg / "node_modules" / "@openai" / "codex-win32-x64"
    vendor = platform_pkg / "vendor" / "x86_64-pc-windows-msvc"
    if not (vendor / "bin" / "codex.exe").is_file():
        raise QualificationError("LAUNCH_CHAIN_VENDOR_MISSING")
    files = [node, entry, pkg / "package.json", platform_pkg / "package.json"]
    files += sorted(p for p in vendor.rglob("*") if p.is_file() and p.suffix.lower() in (".exe", ".dll", ".js", ".cmd", ".ps1"))
    for f in files:
        pinned[str(Path(f).resolve())] = _file_sha256(f)
    return pinned, resolve


def launch_chain_for(spec_id, executable, environ=None):
    if spec_id == "codex_cli" and Path(executable).suffix.lower() == ".cmd":
        return npm_codex_launch_chain(executable, environ)
    if Path(executable).suffix.lower() in (".cmd", ".bat", ".ps1"):
        raise QualificationError("LAUNCH_CHAIN_UNKNOWN_LAUNCHER", Path(executable).name)
    return {}, {}


# ---- record construction ----------------------------------------------------------------------------------------

def build_record(*, client_root, client_id, signer: Ed25519PrivateKey, provider, level, spec_id, executable,
                 executable_args, version, models, evidence_path, qualified_by, notes=None, pinned_files=None,
                 resolve_pins=None, ttl_s=DEFAULT_TTL_S, now=None) -> dict:
    """Build and sign a record from observed facts. The caller is the trusted qualification run of THIS client. The
    evidence file is copied into the client's own qualification store (content-addressed) and hashed there."""
    if not isinstance(provider, str) or not _PROVIDER.fullmatch(provider):
        raise QualificationError("PROVIDER_ID_INVALID")
    if level not in LEVELS:
        raise QualificationError("LEVEL_INVALID", str(level))
    if spec_id not in BUILTIN_SPECS:
        raise QualificationError("SPEC_UNKNOWN", str(spec_id))
    if not isinstance(client_id, str) or not _UUID.fullmatch(client_id):
        raise QualificationError("CLIENT_ID_INVALID")
    exe = Path(executable)
    if not exe.is_file():
        raise QualificationError("EXECUTABLE_MISSING")
    args = [str(a) for a in (executable_args or [])]
    ev = Path(evidence_path)
    if not ev.is_file():
        raise QualificationError("EVIDENCE_MISSING")
    if not isinstance(models, (list, tuple)) or not models:
        raise QualificationError("MODELS_REQUIRED")
    for m in models:
        if m is not None and (not isinstance(m, str) or not _MODEL.fullmatch(m)):
            raise QualificationError("MODEL_ID_INVALID", str(m))
    if version is not None and not isinstance(version, str):
        raise QualificationError("VERSION_INVALID")
    if not isinstance(ttl_s, int) or not 60 <= ttl_s <= MAX_TTL_S:
        raise QualificationError("TTL_INVALID")
    if pinned_files is None and resolve_pins is None:
        pinned_files, resolve_pins = launch_chain_for(spec_id, exe)
    data = ev.read_bytes()
    ev_sha = hashlib.sha256(data).hexdigest()
    ev_name = f"{provider}-{ev_sha[:16]}.json"
    d = evidence_dir(client_root)
    d.mkdir(parents=True, exist_ok=True)
    (d / ev_name).write_bytes(data)
    now = int(time.time() if now is None else now)
    record = {"schema": SCHEMA, "provider": provider, "level": level, "spec_id": spec_id, "client_id": client_id,
              "client_public_key": _public_hex(signer), "executable": str(exe.resolve()), "executable_args": args,
              "executable_sha256": _file_sha256(exe), "pinned_files": dict(sorted((pinned_files or {}).items())),
              "resolve_pins": dict(sorted((resolve_pins or {}).items())), "version": version, "models": list(models),
              "evidence_file": ev_name, "evidence_sha256": ev_sha, "qualified_at": now, "expires_at": now + ttl_s,
              "qualified_by": str(qualified_by), "notes": notes or ""}
    record["record_sha256"] = record_digest(record)
    record["signature"] = signer.sign(_canonical(record)).hex()
    return record


def write_record(client_root, record: dict) -> Path:
    """Atomic write of one provider's record (replaces an older record for the same provider)."""
    validate_shape(record)
    d = qualification_dir(client_root)
    d.mkdir(parents=True, exist_ok=True)
    path = d / (record["provider"] + ".json")
    tmp = path.with_name(path.name + "." + uuid.uuid4().hex + ".tmp")
    with open(tmp, "x", encoding="utf-8") as f:
        json.dump(record, f, indent=1, sort_keys=True)
        f.flush()
        os.fsync(f.fileno())
    os.replace(tmp, path)
    return path


def validate_shape(record) -> dict:
    if not isinstance(record, dict) or set(record) - set(REQUIRED) - set(OPTIONAL) or any(k not in record for k in REQUIRED):
        raise QualificationError("RECORD_SCHEMA")
    if record["schema"] != SCHEMA:
        raise QualificationError("RECORD_SCHEMA", "schema")
    if not isinstance(record["provider"], str) or not _PROVIDER.fullmatch(record["provider"]):
        raise QualificationError("RECORD_SCHEMA", "provider")
    if record["level"] not in LEVELS:
        raise QualificationError("RECORD_SCHEMA", "level")
    if record["spec_id"] not in BUILTIN_SPECS:
        raise QualificationError("RECORD_SCHEMA", "spec_id")
    if not isinstance(record["client_id"], str) or not _UUID.fullmatch(record["client_id"]):
        raise QualificationError("RECORD_SCHEMA", "client_id")
    if not isinstance(record["client_public_key"], str) or not re.fullmatch(r"[0-9a-f]{64}", record["client_public_key"]):
        raise QualificationError("RECORD_SCHEMA", "client_public_key")
    if not isinstance(record["executable"], str) or not record["executable"]:
        raise QualificationError("RECORD_SCHEMA", "executable")
    if not isinstance(record["executable_args"], list) or any(not isinstance(a, str) for a in record["executable_args"]):
        raise QualificationError("RECORD_SCHEMA", "executable_args")
    pf = record["pinned_files"]
    if not isinstance(pf, dict) or any(not isinstance(k, str) or not isinstance(v, str) or not _HEX64.fullmatch(v) for k, v in pf.items()):
        raise QualificationError("RECORD_SCHEMA", "pinned_files")
    rp = record["resolve_pins"]
    if not isinstance(rp, dict) or any(not isinstance(k, str) or not _RESOLVE_NAME.fullmatch(k) or not isinstance(v, str) or v not in pf
                                       for k, v in rp.items()):
        raise QualificationError("RECORD_SCHEMA", "resolve_pins")
    for key in ("executable_sha256", "evidence_sha256", "record_sha256"):
        if not isinstance(record[key], str) or not _HEX64.fullmatch(record[key]):
            raise QualificationError("RECORD_SCHEMA", key)
    if not isinstance(record["evidence_file"], str) or not _EVIDENCE_NAME.fullmatch(record["evidence_file"]):
        raise QualificationError("RECORD_SCHEMA", "evidence_file")
    for key in ("qualified_at", "expires_at"):
        if type(record[key]) is not int:
            raise QualificationError("RECORD_SCHEMA", key)
    if not 0 < record["expires_at"] - record["qualified_at"] <= MAX_TTL_S:
        raise QualificationError("RECORD_SCHEMA", "ttl")
    if record["version"] is not None and not isinstance(record["version"], str):
        raise QualificationError("RECORD_SCHEMA", "version")
    models = record["models"]
    if not isinstance(models, list) or not models or any(m is not None and (not isinstance(m, str) or not _MODEL.fullmatch(m)) for m in models):
        raise QualificationError("RECORD_SCHEMA", "models")
    if not isinstance(record["signature"], str) or not re.fullmatch(r"[0-9a-f]{128}", record["signature"]):
        raise QualificationError("RECORD_SCHEMA", "signature")
    if record_digest(record) != record["record_sha256"]:
        raise QualificationError("RECORD_DIGEST_MISMATCH")
    return record


def verify_trust(record, trust: RecordTrust):
    """Binding + signature. The digest alone is recomputable by anyone; the signature is not (review D1/D3)."""
    if trust is None:
        raise QualificationError("NO_TRUST_ANCHOR")
    if record["client_id"] != trust.client_id or record["client_public_key"] != trust.public_key_hex:
        raise QualificationError("RECORD_CLIENT_MISMATCH")
    try:
        Ed25519PublicKey.from_public_bytes(bytes.fromhex(trust.public_key_hex)).verify(bytes.fromhex(record["signature"]), _canonical(record))
    except (InvalidSignature, ValueError):
        raise QualificationError("RECORD_SIGNATURE_INVALID") from None


def load_records(client_root) -> list:
    """Every record file, parsed or marked unreadable. Never raises for one bad file."""
    out = []
    d = qualification_dir(client_root)
    if not d.is_dir():
        return out
    for p in sorted(d.glob("*.json")):
        try:
            rec = json.loads(p.read_text(encoding="utf-8"))
            validate_shape(rec)
            if rec["provider"] != p.stem:
                raise QualificationError("RECORD_PROVIDER_FILENAME_MISMATCH")
            out.append({"path": str(p), "record": rec, "error": None})
        except (OSError, ValueError) as exc:
            code = exc.code if isinstance(exc, QualificationError) else "RECORD_UNREADABLE"
            out.append({"path": str(p), "record": None, "error": code})
    return out


def client_cli_homes(client_root, create=True) -> dict:
    """ISO-1 (Phase 2 closure, 2026-10-08): the CLI homes of the CLIENT PROFILE, to be set in the worker's environment.

    The worker's sanitized environment points USERPROFILE/HOME at `<client_root>/home`, which isolates Claude Code
    (it resolves its config through the process home). Codex 0.158.0 does NOT: without CODEX_HOME it resolves the
    Windows user profile itself and reads the OWNER's global login (observed: `codex login status` -> "Logged in using
    ChatGPT" with only the profile variables overridden; "Not logged in" once CODEX_HOME names the client profile).
    Pinning CODEX_HOME keeps every Codex probe and executor of this client on the client profile's own login, so a
    shared owner login can never qualify or run a client executor (C7 stop condition "shared client authentication")."""
    home = Path(client_root) / "home"
    pins = {"CODEX_HOME": str(home / ".codex")}
    if create:
        for value in pins.values():
            Path(value).mkdir(parents=True, exist_ok=True)
    return pins


def native_auth_probe(provider, executable, environ=None, timeout_s=30):
    """Live read-only authentication status. True / False / None (unknown). Never logs in, never reads a credential
    file: the CLI's own status command decides, under the same environment allow-list the executor gets."""
    argv = AUTH_STATUS_ARGV.get(provider)
    if argv is None:
        return None
    env = harness_env(AUTH_VARS.get(provider, ()), environ)
    try:
        p = subprocess.run([executable, *argv], capture_output=True, timeout=timeout_s, stdin=subprocess.DEVNULL, env=env)
    except (OSError, subprocess.TimeoutExpired):
        return None
    out = p.stdout.decode("utf-8", "replace")
    err = p.stderr.decode("utf-8", "replace")
    if provider == "claude_code":
        try:
            data = json.loads(out)
            return bool(data.get("loggedIn")) if isinstance(data, dict) else None
        except ValueError:
            return None
    # Codex 0.158.0 prints "Logged in using ChatGPT" on STDERR with exit 0 (Phase 2D defect D-D1: stdout alone read as
    # "not logged in"). "Not logged in" exits non-zero. Both streams are inspected; exit status decides first.
    text = (out + chr(10) + err).lower()
    if p.returncode != 0 or "not logged in" in text:
        return False
    return "logged in" in text


@dataclass(frozen=True)
class ClientComposition:
    registry: HarnessRegistry
    executors: dict
    report: list          # one row per record file: provider, status (QUALIFIED | INVALIDATED), reason, level, ...
    allow_fixture: bool

    def qualified(self):
        return sorted(r["provider"] for r in self.report if r["status"] == "QUALIFIED")


def _spec_for(record) -> ExecutorSpec:
    spec = BUILTIN_SPECS[record["spec_id"]]
    if record["level"] == "FIXTURE_ONLY":
        if record["spec_id"] != GENERIC_NDJSON.executor_id:
            raise QualificationError("FIXTURE_SPEC_REQUIRED")
        return replace(GENERIC_NDJSON, executor_id=record["provider"], stdin="instructions")
    if spec.executor_id != record["provider"]:
        raise QualificationError("SPEC_PROVIDER_MISMATCH")
    return spec


def check_launch_chain(pinned_files, resolve_pins, environ=None):
    """Every pinned file still present with its hash; every resolve pin still resolves to its pinned file on the
    executor PATH. Raises QualificationError. Shared by load-time re-validation and the bridge's per-run check."""
    for path, digest in dict(pinned_files).items():
        if not Path(path).is_file():
            raise QualificationError("LAUNCH_CHAIN_MISSING", Path(path).name)
        if _file_sha256(path) != digest:
            raise QualificationError("LAUNCH_CHAIN_HASH_MISMATCH", Path(path).name)
    for name, path in dict(resolve_pins).items():
        found = shutil.which(name, path=executor_path(environ))
        if not found or _same_file(found, path) is not True:
            raise QualificationError("LAUNCH_CHAIN_RESOLUTION_CHANGED", name)


def _check_evidence(record, client_root):
    p = evidence_dir(client_root) / record["evidence_file"]
    if not p.is_file():
        raise QualificationError("EVIDENCE_MISSING")
    data = p.read_bytes()
    if hashlib.sha256(data).hexdigest() != record["evidence_sha256"]:
        raise QualificationError("EVIDENCE_HASH_MISMATCH")
    try:
        ev = json.loads(data)
    except ValueError:
        raise QualificationError("EVIDENCE_CONTENT_MISMATCH", "not json") from None
    if not isinstance(ev, dict) or ev.get("provider") != record["provider"]:
        raise QualificationError("EVIDENCE_CONTENT_MISMATCH", "provider")
    if record["level"] == "FIXTURE_ONLY":
        if ev.get("fixture") is not True:
            raise QualificationError("EVIDENCE_CONTENT_MISMATCH", "fixture")
        # Fixture evidence MUST name exactly the models it covers; the record may not claim more or other ones
        # (review round 2, R2-2; round 3, R3-1/R3-2: a missing or malformed list is refused, never a crash).
        models = ev.get("models")
        if not isinstance(models, list) or not models or any(m is not None and not isinstance(m, str) for m in models):
            raise QualificationError("EVIDENCE_CONTENT_MISMATCH", "models")
        if models != list(record["models"]):
            raise QualificationError("EVIDENCE_CONTENT_MISMATCH", "models")
        return
    # NATIVE: the direct probe record of the qualification run must show a successful probe of this very executable,
    # at this version. The record qualifies EXACTLY the probed model, nothing more (review round 2, R2-2: a signed
    # record could list models that were never exercised).
    if ev.get("ok") is not True or ev.get("version") != record["version"] or ev.get("executable_sha256") != record["executable_sha256"]:
        raise QualificationError("EVIDENCE_CONTENT_MISMATCH", "probe")
    if list(record["models"]) != [ev.get("model")]:
        raise QualificationError("EVIDENCE_CONTENT_MISMATCH", "model")


def revalidate(record, *, client_root, trust: RecordTrust, allow_fixture=False, now=None, environ=None) -> tuple:
    """-> (spec, resolved executable, args) or raises QualificationError with the invalidation reason."""
    verify_trust(record, trust)
    if int(time.time() if now is None else now) >= record["expires_at"]:
        raise QualificationError("RECORD_EXPIRED")
    if record["level"] == "FIXTURE_ONLY" and not allow_fixture:
        raise QualificationError("LEVEL_NOT_ALLOWED", "FIXTURE_ONLY")
    spec = _spec_for(record)
    _check_evidence(record, client_root)
    exe = record["executable"]
    cmd = resolve_command(exe)
    if not cmd or not Path(exe).is_file() or _same_file(cmd[0], exe) is not True:
        raise QualificationError("EXECUTABLE_MISSING")
    if _file_sha256(exe) != record["executable_sha256"]:
        raise QualificationError("EXECUTABLE_HASH_MISMATCH")
    if record["level"] == "NATIVE_QUALIFIED" and Path(exe).suffix.lower() in (".cmd", ".bat", ".ps1") and not record["pinned_files"]:
        raise QualificationError("LAUNCH_CHAIN_NOT_PINNED")
    check_launch_chain(record["pinned_files"], record["resolve_pins"], environ)
    for a in record["executable_args"]:
        if Path(a).is_absolute() and Path(a).suffix == ".py" and not Path(a).is_file():
            raise QualificationError("EXECUTABLE_ARGS_MISSING")
    probe = probe_version([exe, *record["executable_args"]])
    if not probe["installed"] or probe["version"] != record["version"] or record["version"] is None:
        raise QualificationError("VERSION_MISMATCH", f"{probe.get('version')} != {record['version']}")
    return spec, exe, list(record["executable_args"])


def compose_client(client_root, *, trust: RecordTrust, allow_fixture=False, auth_probe=None, environ=None,
                   adapters_factory=None, now=None, clock=None) -> ClientComposition:
    """Phase 1 `HarnessRegistry` (all adapters, nothing qualified) plus every persisted record that re-validates now
    for THIS client (`trust`).

    `auth_probe(harness_id) -> True|False|None` defaults to the live CLI status probe for providers with a valid record
    (fixture records are authenticated by definition) and None (AUTH_UNVERIFIED) for everything else. The registry calls
    it on every `discover()`/`selectable()`, i.e. immediately before each bridge execution: nothing is cached."""
    from uri_harness_adapters import default_registry
    factory = adapters_factory or default_registry
    # `now` fixes composition time (tests); `clock` is consulted at every later re-validation (default: wall clock).
    now_fn = clock or (lambda: time.time() if now is None else now)
    rows, executables, bindings, exe_of, levels, composed = [], {}, {}, {}, {}, {}
    for item in load_records(client_root):
        rec = item["record"]
        if rec is None:
            rows.append({"provider": Path(item["path"]).stem, "status": "INVALIDATED", "reason": item["error"], "path": item["path"]})
            continue
        try:
            spec, exe, args = revalidate(rec, client_root=client_root, trust=trust, allow_fixture=allow_fixture, now=now_fn(), environ=environ)
        except QualificationError as exc:
            rows.append({"provider": rec["provider"], "status": "INVALIDATED", "reason": exc.code, "detail": exc.detail,
                         "level": rec["level"], "path": item["path"]})
            continue
        executables[rec["provider"]] = [exe, *args]
        exe_of[rec["provider"]], levels[rec["provider"]] = exe, rec["level"]
        composed[rec["provider"]] = (item["path"], rec["record_sha256"])
        bindings[rec["provider"]] = ExecutorBinding(spec=spec, resolved_executable=exe, extra_argv=tuple(args), version=rec["version"],
                                                   executable_sha256=rec["executable_sha256"], qualified_models=tuple(rec["models"]),
                                                   pinned_files=tuple(sorted(rec["pinned_files"].items())),
                                                   resolve_pins=tuple(sorted(rec["resolve_pins"].items())),
                                                   revalidate=(lambda p=rec["provider"]: still_valid(p)))
        rows.append({"provider": rec["provider"], "status": "QUALIFIED", "reason": None, "level": rec["level"], "models": list(rec["models"]),
                     "executable": exe, "executable_sha256": rec["executable_sha256"], "pinned_files": len(rec["pinned_files"]),
                     "version": rec["version"], "evidence_sha256": rec["evidence_sha256"], "qualified_at": rec["qualified_at"],
                     "expires_at": rec["expires_at"], "path": item["path"]})

    def still_valid(provider):
        """None while the record composed for `provider` still holds NOW: same record bytes on disk (no silent swap
        for another record, even a validly signed one), and a full re-validation (signature, expiry, evidence, launch
        chain, version). Otherwise the reason code. Review round 2, R2-1."""
        path, digest = composed[provider]
        try:
            rec_now = validate_shape(json.loads(Path(path).read_text(encoding="utf-8")))
        except (OSError, ValueError) as exc:
            return exc.code if isinstance(exc, QualificationError) else "RECORD_UNREADABLE"
        if rec_now["record_sha256"] != digest:
            return "RECORD_CHANGED_SINCE_COMPOSITION"
        try:
            revalidate(rec_now, client_root=client_root, trust=trust, allow_fixture=allow_fixture, now=now_fn(), environ=environ)
        except QualificationError as exc:
            return exc.code
        return None

    def probe(harness_id):
        if harness_id not in exe_of:
            return None
        if still_valid(harness_id) is not None:
            return None            # qualification no longer holds: AUTH_UNVERIFIED -> not usable (fail closed)
        if levels[harness_id] == "FIXTURE_ONLY":
            return True
        if auth_probe is not None:
            return auth_probe(harness_id)
        return native_auth_probe(harness_id, exe_of[harness_id], environ)

    registry = factory(executables, auth_probe=probe)
    for row in rows:
        if row["status"] != "QUALIFIED":
            continue
        p = row["provider"]
        if p not in registry.adapters or registry.adapters[p].refused:
            row.update(status="INVALIDATED", reason="PROVIDER_REFUSED_OR_UNKNOWN")
            bindings.pop(p, None)
            continue
        registry.qualify(p, row["level"], row["evidence_sha256"])
    return ClientComposition(registry=registry, executors=bindings, report=rows, allow_fixture=bool(allow_fixture))
